// tablet/src/offline/flushQueue.test.ts
import { describe, it, expect, vi, beforeEach } from 'vitest'

vi.mock('../api/pings')
vi.mock('../api/visits')
vi.mock('../api/tasks')
vi.mock('./queueStore')

import { flushQueue } from './flushQueue'
import { ApiError } from '../api/client'
import { submitPing } from '../api/pings'
import { checkIn, checkOut } from '../api/visits'
import { completeTask } from '../api/tasks'
import { getQueue, removeFromQueue } from './queueStore'

const mockedSubmitPing = vi.mocked(submitPing)
const mockedCheckIn = vi.mocked(checkIn)
const mockedCheckOut = vi.mocked(checkOut)
const mockedCompleteTask = vi.mocked(completeTask)
const mockedGetQueue = vi.mocked(getQueue)
const mockedRemoveFromQueue = vi.mocked(removeFromQueue)

beforeEach(() => {
  vi.clearAllMocks()
  mockedRemoveFromQueue.mockResolvedValue(undefined)
})

describe('flushQueue', () => {
  it('sends each queued action in order and removes it on success', async () => {
    mockedGetQueue.mockResolvedValue([
      {
        id: 'a', type: 'ping', queuedAt: 't',
        payload: { recorded_at: 't', latitude: 1, longitude: 1, idempotency_key: 'a' },
      },
      { id: 'b', type: 'complete_task', queuedAt: 't', payload: { taskId: 'task-1' } },
    ])
    // @ts-expect-error -- test doubles don't need the real Ping/Task return shape
    mockedSubmitPing.mockResolvedValue({})
    // @ts-expect-error -- test doubles don't need the real Ping/Task return shape
    mockedCompleteTask.mockResolvedValue({})

    await flushQueue()

    expect(mockedSubmitPing).toHaveBeenCalledTimes(1)
    expect(mockedCompleteTask).toHaveBeenCalledWith('task-1')
    expect(mockedRemoveFromQueue).toHaveBeenCalledWith('a')
    expect(mockedRemoveFromQueue).toHaveBeenCalledWith('b')
  })

  it('stops at the first transient failure and does not attempt later items', async () => {
    mockedGetQueue.mockResolvedValue([
      { id: 'a', type: 'check_in', queuedAt: 't', payload: { idempotency_key: 'a', latitude: 1, longitude: 1 } },
      { id: 'b', type: 'check_out', queuedAt: 't', payload: { visitId: 'visit-1' } },
    ])
    mockedCheckIn.mockRejectedValue(new TypeError('network request failed'))

    await flushQueue()

    expect(mockedCheckOut).not.toHaveBeenCalled()
    expect(mockedRemoveFromQueue).not.toHaveBeenCalled()
  })

  it('drops an item on a 409 conflict (already applied server-side) without retrying', async () => {
    mockedGetQueue.mockResolvedValue([
      { id: 'a', type: 'check_out', queuedAt: 't', payload: { visitId: 'visit-1' } },
    ])
    mockedCheckOut.mockRejectedValue(new ApiError(409, 'visit already checked out'))

    await flushQueue()

    expect(mockedRemoveFromQueue).toHaveBeenCalledWith('a')
  })

  it('drops an item on a 404 (resource genuinely gone) without retrying', async () => {
    mockedGetQueue.mockResolvedValue([
      { id: 'a', type: 'complete_task', queuedAt: 't', payload: { taskId: 'ghost-task' } },
    ])
    mockedCompleteTask.mockRejectedValue(new ApiError(404, 'task not found'))

    await flushQueue()

    expect(mockedRemoveFromQueue).toHaveBeenCalledWith('a')
  })

  it('does NOT drop an item on a 401 -- not authenticated yet is not the same as done, never discard', async () => {
    mockedGetQueue.mockResolvedValue([
      {
        id: 'a', type: 'ping', queuedAt: 't',
        payload: { recorded_at: 't', latitude: 1, longitude: 1, idempotency_key: 'a' },
      },
    ])
    mockedSubmitPing.mockRejectedValue(new ApiError(401, 'no refresh token available'))

    await flushQueue()

    expect(mockedRemoveFromQueue).not.toHaveBeenCalled()
  })
})
```

