import { getAccessToken, getRefreshToken, setTokens } from '../auth/preferencesStore'

const API_BASE = import.meta.env.VITE_API_BASE_URL as string

export class ApiError extends Error {
  status: number
  constructor(status: number, message: string) {
    super(message)
    this.status = status
  }
}

async function doFetch(path: string, options: RequestInit, accessToken: string | null): Promise<Response> {
  const headers = new Headers(options.headers)
  if (accessToken) headers.set('Authorization', `Bearer ${accessToken}`)
  if (options.body && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json')
  return fetch(`${API_BASE}${path}`, { ...options, headers })
}

async function refreshAccessToken(): Promise<string> {
  const refreshToken = await getRefreshToken()
  if (!refreshToken) throw new ApiError(401, 'no refresh token available')

  const response = await fetch(`${API_BASE}/api/v1/auth/refresh`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ refresh_token: refreshToken }),
  })
  if (!response.ok) {
    await setTokens(null, null)
    throw new ApiError(401, 'refresh failed')
  }
  const tokens = await response.json()
  await setTokens(tokens.access_token, tokens.refresh_token)
  return tokens.access_token
}

export async function apiFetch<T>(path: string, options: RequestInit = {}): Promise<T> {
  let response = await doFetch(path, options, getAccessToken())

  if (response.status === 401) {
    const newAccessToken = await refreshAccessToken()
    response = await doFetch(path, options, newAccessToken)
  }

  if (!response.ok) {
    throw new ApiError(response.status, `request to ${path} failed with ${response.status}`)
  }

  if (response.status === 204) return undefined as T
  return response.json()
}

// tablet/src/offline/queueStore.ts
import { Preferences } from '@capacitor/preferences'
import type { QueuedAction } from './types'

const QUEUE_KEY = 'atlas_offline_queue'

// ponytail: in-memory promise-chain lock. Capacitor apps are single-instance
// (one WebView, no multi-tab), so this is sufficient to serialize
// read-modify-write access against interleaved async calls in this process --
// upgrade to a real cross-process lock only if this app ever runs in more
// than one WebView context at once, which it doesn't.
let lock: Promise<unknown> = Promise.resolve()

function withLock<T>(fn: () => Promise<T>): Promise<T> {
  const result = lock.then(fn, fn)
  lock = result.catch(() => {})
  return result
}

async function readQueue(): Promise<QueuedAction[]> {
  const { value } = await Preferences.get({ key: QUEUE_KEY })
  return value ? (JSON.parse(value) as QueuedAction[]) : []
}

async function writeQueue(queue: QueuedAction[]): Promise<void> {
  await Preferences.set({ key: QUEUE_KEY, value: JSON.stringify(queue) })
}

export function getQueue(): Promise<QueuedAction[]> {
  return withLock(readQueue)
}

export function enqueue(action: QueuedAction): Promise<void> {
  return withLock(async () => {
    const queue = await readQueue()
    queue.push(action)
    await writeQueue(queue)
  })
}

export function removeFromQueue(id: string): Promise<void> {
  return withLock(async () => {
    const queue = await readQueue()
    await writeQueue(queue.filter((a) => a.id !== id))
  })
}

