// tablet/src/offline/flushQueue.ts
import { ApiError } from '../api/client'
import { submitPing } from '../api/pings'
import { checkIn, checkOut } from '../api/visits'
import { completeTask } from '../api/tasks'
import { getQueue, removeFromQueue } from './queueStore'
import type { QueuedAction } from './types'

// 404 (resource genuinely gone) and 409 (a prior attempt already succeeded
// server-side, e.g. the response was lost after the server committed) are
// the only failures that mean "stop retrying, this is done or dead."
// Everything else -- 401/403 (not authenticated *yet*, not "delete this"),
// 5xx, raw network errors -- is transient and must be retried later. Getting
// this wrong toward "drop on 401" silently deletes a rep's real check-in the
// first time the app is relaunched before they log back in.
function isPermanentFailure(err: unknown): boolean {
  return err instanceof ApiError && (err.status === 404 || err.status === 409)
}

async function sendAction(action: QueuedAction): Promise<void> {
  switch (action.type) {
    case 'ping':
      await submitPing(action.payload)
      return
    case 'check_in':
      await checkIn(action.payload)
      return
    case 'check_out':
      await checkOut(action.payload.visitId)
      return
    case 'complete_task':
      await completeTask(action.payload.taskId)
      return
  }
}

let isFlushing = false

export async function flushQueue(): Promise<void> {
  if (isFlushing) return
  isFlushing = true
  try {
    const queue = await getQueue()
    for (const action of queue) {
      try {
        await sendAction(action)
        await removeFromQueue(action.id)
      } catch (err) {
        if (isPermanentFailure(err)) {
          await removeFromQueue(action.id)
          continue
        }
        return // stop here -- preserve order, retry this and later items next time
      }
    }
  } finally {
    isFlushing = false
  }
}

// tablet/src/location/TrackingToggle.tsx
import { useRef, useState } from 'react'
import { startWatching, stopWatching } from './backgroundLocation'
import { usePingPoster } from './usePingPoster'
import { submitPing } from '../api/pings'
import { getLatestLocation, setLatestLocation } from './locationStore'
import { enqueue } from '../offline/queueStore'

const PING_POST_INTERVAL_MS = 30_000

export function TrackingToggle() {
  const [isTracking, setIsTracking] = useState(false)
  const [lastPostedAt, setLastPostedAt] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const watcherIdRef = useRef<string | null>(null)

  usePingPoster(
    () => (isTracking ? getLatestLocation() : null),
    PING_POST_INTERVAL_MS,
    (location) => {
      const input = {
        recorded_at: new Date(location.time ?? Date.now()).toISOString(),
        latitude: location.latitude,
        longitude: location.longitude,
        accuracy: location.accuracy,
        idempotency_key: crypto.randomUUID(),
      }
      submitPing(input)
        .then(() => setLastPostedAt(new Date().toLocaleTimeString()))
        .catch(async () => {
          await enqueue({ id: input.idempotency_key, type: 'ping', queuedAt: new Date().toISOString(), payload: input })
          setLastPostedAt(`${new Date().toLocaleTimeString()} (queued -- offline)`)
        })
    },
  )

  async function handleToggle() {
    setError(null)
    try {
      if (isTracking) {
        // ponytail: stopWatching is a native-bridge call and can reject too
        // (e.g. watcher already gone). Wrapped in the same try/catch as the
        // start branch so a rejection surfaces an error instead of leaving
        // isTracking/watcherIdRef stuck out of sync with reality.
        if (watcherIdRef.current) await stopWatching(watcherIdRef.current)
        watcherIdRef.current = null
        setIsTracking(false)
        return
      }
      const id = await startWatching((location) => {
        setLatestLocation(location)
      })
      watcherIdRef.current = id
      setIsTracking(true)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update location tracking')
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <h1 className="text-2xl font-semibold text-gray-900 mb-4">Atlas Field Force</h1>
      <button
        onClick={handleToggle}
        className={`px-4 py-2 rounded text-white ${isTracking ? 'bg-red-600' : 'bg-blue-600'}`}
      >
        {isTracking ? 'Stop tracking' : 'Start tracking'}
      </button>
      {lastPostedAt && <p className="mt-4 text-sm text-gray-600">Last location sent: {lastPostedAt}</p>}
      {error && <p className="mt-4 text-sm text-red-600">{error}</p>}
    </div>
  )
}

// tablet/src/offline/useSyncQueue.ts
import { useEffect } from 'react'
import { Network } from '@capacitor/network'
import { flushQueue } from './flushQueue'

// Fallback for the (rare) case a queued item fails for a reason other than
// being offline -- e.g. a transient 5xx while the device stayed connected
// the whole time, so no reconnect event ever fires to retry it.
const QUEUE_FLUSH_FALLBACK_INTERVAL_MS = 30_000

export function useSyncQueue(): void {
  useEffect(() => {
    flushQueue()

    let previousConnected: boolean | null = null
    Network.getStatus().then((status) => {
      previousConnected = status.connected
    })

    const listenerPromise = Network.addListener('networkStatusChange', (status) => {
      if (status.connected && previousConnected === false) {
        flushQueue()
      }
      previousConnected = status.connected
    })

    const intervalId = setInterval(() => {
      flushQueue()
    }, QUEUE_FLUSH_FALLBACK_INTERVAL_MS)

    return () => {
      listenerPromise.then((handle) => handle.remove())
      clearInterval(intervalId)
    }
  }, [])
}
